<?php
if(!defined('ABSPATH'))exit;
function dgs_showcase_active(){$p=get_option('dgs_pages',array());return is_front_page()||(!empty($p['home'])&&is_page((int)$p['home']))||(!empty($p['about'])&&is_page((int)$p['about']));}
function dgs_showcase_icon($name){$paths=array('image'=>'M3 3h18v18H3zM3 17l6-6 4 4 3-3 5 5M15 8a1.5 1.5 0 1 0 0-.01','target'=>'M12 3a9 9 0 1 0 9 9M12 7a5 5 0 1 0 5 5M12 12l9-9M17 3h4v4','building'=>'M9 3h8v19H9zM3 10h6v12H3zM17 8h4v14h-4M12 6h2M12 10h2M12 14h2M12 18h2M5 13h1M5 17h1M19 11h1M19 15h1','person'=>'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M4 22v-3c0-7 16-7 16 0v3','settings'=>'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1zM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8');if($name==='teacher'&&function_exists('dgs_login_icon'))return dgs_login_icon('teacher');return isset($paths[$name])?'<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="'.$paths[$name].'"/></svg>':dgs_portal_icon($name);}
function dgs_showcase_heading($title,$icon='study',$link='',$label='مشاهده همه'){return '<div class="dsh-section-heading"><h2>'.dgs_showcase_icon($icon).esc_html($title).'</h2>'.($link?'<a class="dsh-soft-button" href="'.esc_url($link).'">'.esc_html($label).dgs_portal_icon('arrow').'</a>':'').'</div>';}
function dgs_showcase_picture($key,$class='',$alt=''){$id=absint(dgs_showcase_setting($key));if(dgs_showcase_image_valid($id))return '<div class="dsh-picture '.esc_attr($class).'">'.wp_get_attachment_image($id,'large',false,array('alt'=>$alt,'loading'=>$key==='hero_image'?'eager':'lazy','fetchpriority'=>$key==='hero_image'?'high':'auto')).'</div>';return '<div class="dsh-picture dsh-reference '.esc_attr($class).'" role="img" aria-label="'.esc_attr($alt.' — تصویر نمایشی طرح').' "></div>';}
function dgs_showcase_teacher_posts($limit=20){return get_posts(array('post_type'=>'dgs_teacher','post_status'=>'publish','numberposts'=>$limit,'orderby'=>'menu_order title','order'=>'ASC','meta_query'=>array('relation'=>'OR',array('key'=>'_dgs_group','value'=>'teacher'),array('key'=>'_dgs_group','compare'=>'NOT EXISTS'))));}
function dgs_showcase_people($posts,$class='',$staff=false){if(!$posts)return dgs_empty($staff?'اطلاعات کادر مدرسه هنوز منتشر نشده است.':'معرفی اساتید پس از انتشار رزومه‌ها نمایش داده می‌شود.');$out='<div class="dsh-people '.esc_attr($class).'">';foreach($posts as $p){$out.='<article class="dsh-person"><a class="dsh-person-photo" href="'.esc_url(get_permalink($p)).'">'.dgs_avatar($p->ID,'medium').'</a><div><h3><a href="'.esc_url(get_permalink($p)).'">'.esc_html($p->post_title).'</a></h3><span>'.esc_html(get_post_meta($p->ID,'_dgs_specialty',true)).'</span>'.($staff?'<p>'.esc_html(wp_trim_words(wp_strip_all_tags($p->post_excerpt?:$p->post_content),18)).'</p>':'').'</div></article>';}$out.='</div>';return $out;}
function dgs_showcase_teacher_strip(){return '<section class="dsh-card dsh-teachers-strip"><div class="dsh-strip-copy"><h2>'.dgs_portal_icon('users').' اساتید مدرسه</h2><p>آشنایی با اساتید و تخصص‌های آموزشی مدرسه دانشگران</p><a class="dg-btn" href="'.esc_url(dgs_page_url('teachers')).'">'.dgs_portal_icon('users').' مشاهده اساتید</a></div><div class="dsh-carousel"><div class="dsh-carousel-controls"><button type="button" data-dsh-scroll="prev" aria-label="اساتید قبلی">‹</button><button type="button" data-dsh-scroll="next" aria-label="اساتید بعدی">›</button></div>'.dgs_showcase_people(dgs_showcase_teacher_posts(),'dsh-people-scroll').'</div></section>';}
function dgs_showcase_featured(){
 $out='<section class="dsh-card dsh-featured"><div class="dsh-strip-copy"><h2>'.dgs_portal_icon('trophy').' دانش‌آموز برگزیده</h2><p>معرفی دانش‌آموزان برگزیده بر اساس اطلاعات منتشرشده مدرسه</p></div><div class="dsh-featured-main"><div class="dsh-featured-tabs" role="tablist" aria-label="بازه برگزیده">';$periods=array('week'=>'هفته','month'=>'ماه','term'=>'ترم','year'=>'سال');foreach($periods as $key=>$label)$out.='<button type="button" role="tab" id="dsh-tab-'.$key.'" aria-controls="dsh-star-'.$key.'" aria-selected="'.($key==='week'?'true':'false').'" tabindex="'.($key==='week'?'0':'-1').'">'.esc_html($label).'</button>';$out.='</div>';
 foreach($periods as $key=>$label){$posts=get_posts(array('post_type'=>'dgs_star','post_status'=>'publish','numberposts'=>1,'meta_key'=>'_dgs_period','meta_value'=>$key,'orderby'=>'date','order'=>'DESC'));$out.='<div role="tabpanel" id="dsh-star-'.$key.'" aria-labelledby="dsh-tab-'.$key.'" '.($key==='week'?'':'hidden').'>';if(!$posts)$out.=dgs_empty('برگزیده '.$label.' هنوز اعلام نشده است.');else{$p=$posts[0];$out.='<div class="dsh-star-content"><div class="dsh-star-photo">'.dgs_avatar($p->ID,'medium').'</div><div><h3>'.esc_html($p->post_title).'</h3><p>'.esc_html(get_post_meta($p->ID,'_dgs_star_class',true)).'</p><strong>'.esc_html(get_post_meta($p->ID,'_dgs_achievement',true)).'</strong></div><div class="dsh-award" aria-hidden="true">'.dgs_portal_icon('trophy').'</div></div>';}$out.='</div>';}
 return $out.'</div></section>';
}
function dgs_showcase_news($type){$label=$type==='school'?'اخبار مدرسه':'اخبار آموزش و پرورش';$posts=get_posts(array('post_type'=>'post','post_status'=>'publish','numberposts'=>3,'category_name'=>$type==='school'?'school-news':'ministry-news','ignore_sticky_posts'=>true));$out='<section class="dsh-card">'.dgs_showcase_heading($label,$type==='school'?'requests':'education');if(!$posts)$out.=dgs_empty('خبر تازه‌ای در این بخش منتشر نشده است.');foreach($posts as $p){$out.='<article class="dsh-news-row">';if(has_post_thumbnail($p))$out.='<a class="dsh-news-photo" href="'.esc_url(get_permalink($p)).'">'.get_the_post_thumbnail($p,'thumbnail',array('loading'=>'lazy')).'</a>';$out.='<div><h3><a href="'.esc_url(get_permalink($p)).'">'.esc_html($p->post_title).'</a></h3><small>'.esc_html(dgs_display_date(get_post_timestamp($p))).'</small></div></article>';}$out.='<a class="dsh-soft-button dsh-news-more" href="'.esc_url(add_query_arg('news_tab',$type,dgs_page_url('news'))).'">مشاهده همه '.esc_html($label).dgs_portal_icon('arrow').'</a></section>';return $out;}
function dgs_showcase_gallery($compact=false){return dgs_gallery_preview($compact?8:4);}
function dgs_showcase_roles(){$out='<section class="dsh-card dsh-role-section"><div class="dsh-strip-copy"><h2>'.dgs_portal_icon('login').' ورود به سامانه مدرسه</h2><p>دسترسی به پنل اختصاصی بر اساس نقش شما در مدرسه</p></div><div class="dsh-role-grid">';foreach(array('student'=>array('education','ورود دانش‌آموز','مشاهده کلاس‌ها، نمرات و اطلاعیه‌ها'),'teacher'=>array('teacher','ورود معلم','برنامه کلاس‌ها، نمرات و فعالیت‌های آموزشی'),'manager'=>array('users','ورود مدیر / مشاور','مدیریت مدرسه و پیگیری امور آموزشی')) as $role=>$v)$out.='<article>'.dgs_showcase_icon($v[0]).'<h3>'.esc_html($v[1]).'</h3><p>'.esc_html($v[2]).'</p><a class="dg-btn" href="'.esc_url(add_query_arg('login_role',$role,dgs_page_url('portal'))).'">ورود به پنل '.dgs_portal_icon('arrow').'</a></article>';return $out.'</div></section>';}
function dgs_showcase_home(){
 $name=dgs_setting('school_name','مدرسه دانشگران');$out='<div class="dsh-page dsh-home"><section class="dsh-home-hero"><div><h1>'.esc_html($name).'</h1><span class="dsh-chip">دبیرستان دوره دوم (پایه‌های دهم، یازدهم و دوازدهم)</span><p>'.nl2br(esc_html(dgs_showcase_setting('hero_text'))).'</p><a class="dg-btn" href="'.esc_url(dgs_page_url('admission')).'">'.dgs_portal_icon('edit').' پیش‌ثبت‌نام مدرسه</a><a class="dg-btn dg-btn-outline" href="'.esc_url(dgs_page_url('contact').'#counseling').'">'.dgs_portal_icon('users').' درخواست مشاوره حضوری</a></div>'.dgs_showcase_picture('hero_image','dsh-hero-picture','نمای مدرسه دانشگران').'</section><section class="dsh-card dsh-intro"><div>'.dgs_showcase_heading('معرفی مدرسه دانشگران','study').'<p>'.nl2br(esc_html(dgs_showcase_setting('intro'))).'</p><a class="dsh-soft-button" href="'.esc_url(dgs_page_url('about')).'">مشاهده بیشتر درباره مدرسه '.dgs_portal_icon('arrow').'</a></div>'.dgs_showcase_picture('intro_image','dsh-intro-picture','معرفی مدرسه').'</section>'.dgs_showcase_teacher_strip().dgs_showcase_featured().'<div class="dsh-two">'.dgs_showcase_news('school').dgs_showcase_news('ministry').'</div><section class="dsh-card">'.dgs_showcase_heading('مدیریت و عوامل آموزشی','users').dgs_showcase_people(array_slice(dgs_showcase_staff(),0,3),'dsh-staff-horizontal',true).'</section>'.dgs_showcase_gallery(true).dgs_showcase_roles().'</div>';return $out;
}
function dgs_showcase_director($staff){$selected=absint(dgs_showcase_setting('director'));foreach($staff as $p)if($p->ID===$selected)return $p;foreach($staff as $p){$role=get_post_meta($p->ID,'_dgs_specialty',true);if(strpos($role,'مدیر')!==false&&strpos($role,'معاون')===false)return $p;}return null;}
function dgs_showcase_about(){
 $staff=dgs_showcase_staff();$director=dgs_showcase_director($staff);$deputies=array_values(array_filter($staff,function($p){return strpos(get_post_meta($p->ID,'_dgs_specialty',true),'معاون')!==false;}));$teachers=array_slice(dgs_showcase_teacher_posts(),0,3);$out='<div class="dsh-page dsh-about"><section class="dsh-about-hero"><div><h1>معرفی مدرسه و کادر آموزشی</h1><p>آشنایی با مدرسه دانشگران، رسالت آموزشی، امکانات و تیم آموزشی ما در دوره دوم متوسطه</p></div>'.dgs_showcase_picture('hero_image','dsh-hero-picture','نمای مدرسه').'</section><div class="dsh-overview"><section class="dsh-card">'.dgs_showcase_heading('درباره مدرسه دانشگران','building').'<p>'.nl2br(esc_html(dgs_showcase_setting('intro'))).'</p></section><section class="dsh-card">'.dgs_showcase_heading('رسالت ما','target').'<p>'.nl2br(esc_html(dgs_showcase_setting('mission'))).'</p></section><section class="dsh-card">'.dgs_showcase_heading('پایه‌های تحصیلی','education').'<p>متوسطه دوم (دوره دوم دبیرستان)</p><div class="dsh-grade-chips"><span>پایه دهم</span><span>پایه یازدهم</span><span>پایه دوازدهم</span></div></section></div><section class="dsh-card dsh-director">'.dgs_showcase_heading('مدیر مدرسه','person');if($director){$text=dgs_showcase_setting('director_text');$out.='<div class="dsh-director-row"><div class="dsh-director-photo">'.dgs_avatar($director->ID,'large').'</div><div><h3>'.esc_html($director->post_title).'</h3><p>'.nl2br(esc_html($text?:wp_strip_all_tags($director->post_content))).'</p></div></div>';}else $out.=dgs_empty('اطلاعات مدیر مدرسه هنوز تکمیل نشده است.');$out.='</section><div class="dsh-team-columns"><section class="dsh-card">'.dgs_showcase_heading('برخی از اعضای کادر آموزشی','education').dgs_showcase_people($teachers,'dsh-team-cards').'</section><section class="dsh-card">'.dgs_showcase_heading('کادر معاونت','users').dgs_showcase_people(array_slice($deputies,0,3),'dsh-team-cards',true).'</section></div>'.dgs_showcase_gallery().'<section class="dsh-card">'.dgs_showcase_heading('امکانات و خدمات آموزشی','settings').'<div class="dsh-facilities">';$lines=array_filter(array_map('trim',preg_split('/\r?\n/',(string)dgs_showcase_setting('facilities'))));$icons=array('classes','education','study','users','medal','home');foreach(array_slice($lines,0,12) as $i=>$line){$parts=explode('|',$line,2);$out.='<article>'.dgs_portal_icon($icons[$i%count($icons)]).'<strong>'.esc_html(trim($parts[0])).'</strong><p>'.esc_html(trim($parts[1]??'')).'</p></article>';}if(!$lines)$out.=dgs_empty('فهرست امکانات مدرسه پس از تکمیل اطلاعات نمایش داده می‌شود.');$out.='</div></section><div class="dsh-about-bottom"><section class="dsh-admission"><div>'.dgs_showcase_heading('پیش‌ثبت‌نام مدرسه','timetable').'<p>'.nl2br(esc_html(dgs_showcase_setting('admission_text'))).'</p></div><a class="dg-btn" href="'.esc_url(dgs_page_url('admission')).'">پیش‌ثبت‌نام '.dgs_portal_icon('arrow').'</a></section><section class="dsh-card dsh-contact">'.dgs_showcase_heading('ارتباط با ما','phone');foreach(array('address'=>array('pin','نشانی'),'phone'=>array('phone','تلفن'),'office_hours'=>array('timetable','ساعات پاسخ‌گویی')) as $key=>$v){$value=dgs_setting($key);if($value)$out.='<p>'.dgs_portal_icon($v[0]).'<b>'.esc_html($v[1]).':</b> '.esc_html($value).'</p>';}$out.='<a href="'.esc_url(dgs_page_url('contact')).'">راه‌های ارتباطی مدرسه '.dgs_portal_icon('arrow').'</a></section></div></div>';return $out;
}
add_action('init',function(){add_shortcode('daneshgaran_home','dgs_showcase_home');add_shortcode('daneshgaran_about','dgs_showcase_about');},40);
add_filter('template_include',function($template){if(get_template()!=='daneshgaran'||!dgs_showcase_active())return $template;if(function_exists('dgs_elementor_converted')&&dgs_elementor_converted()){if(in_array(get_post_meta(get_queried_object_id(),'_wp_page_template',true),array('elementor_canvas','elementor_header_footer'),true))return $template;}elseif(is_preview()||isset($_GET['elementor-preview']))return $template;return DGS_PATH.'includes/showcase-template.php';},100);
add_action('wp_enqueue_scripts',function(){if(!dgs_showcase_active())return;if(function_exists('dgs_elementor_register_assets')){dgs_elementor_register_assets();wp_enqueue_style('dgs-showcase');wp_enqueue_script('dgs-showcase');return;}wp_register_style('dgs-showcase',false,array(),DGS_VERSION);wp_enqueue_style('dgs-showcase');wp_add_inline_style('dgs-showcase',str_replace('SHOWCASE_REFERENCE_URL',esc_url_raw(DGS_URL.'assets/showcase-reference.jpg'),file_get_contents(DGS_PATH.'assets/showcase.css')));wp_register_script('dgs-showcase',false,array(),DGS_VERSION,true);wp_enqueue_script('dgs-showcase');wp_add_inline_script('dgs-showcase',file_get_contents(DGS_PATH.'assets/showcase.js'));});
add_filter('body_class',function($classes){if(dgs_showcase_active())$classes[]='dsh-showcase';return $classes;});
// Elementor's saved page can enqueue addon scripts even when this template replaces its content.
// Initialize its normal frontend configuration without rendering the old layout a second time.
add_action('wp_enqueue_scripts',function(){if(get_template()==='daneshgaran'&&dgs_showcase_active()&&!is_preview()&&!isset($_GET['elementor-preview'])&&class_exists('\\Elementor\\Plugin')&&isset(\Elementor\Plugin::$instance->frontend))\Elementor\Plugin::$instance->frontend->enqueue_scripts();},90);
